function renderWorldQuestBag(root) {
  if (!S.hero) return;
  const bag=root.querySelector('.az573-bag'), count=root.querySelector('.az573-count'), detail=root.querySelector('.az573-inspect');
  if (!bag || !count || !detail) return;
  const rows=worldQuestItems().filter(item=>inventoryCount(S.hero.items,item.id)>0);
  if (!rows.length) return;
  for (const item of rows) {
    const n=inventoryCount(S.hero.items,item.id), cell=document.createElement('div');
    const button=gearButton('Древесина',function () { (root.querySelector('.az-gear-footer')||detail).textContent=item.name+' ×'+n+' · Предмет задания. Нельзя надеть или продать.'; });
    button.className='az573-cell';
    button.style.cssText='font-size:10px;overflow-wrap:anywhere';
    button.setAttribute('aria-label',item.name+', количество '+n+', предмет задания');
    const quantity=document.createElement('small'); quantity.textContent='×'+n;
    cell.append(button,quantity); bag.append(cell);
  }
  const gear=gearItems.filter(item=>bagItemCount(S.hero,item)>0);
  count.textContent=(gear.length+rows.length)+' типов · '+(gear.reduce((sum,item)=>sum+bagItemCount(S.hero,item),0)+rows.reduce((sum,item)=>sum+inventoryCount(S.hero.items,item.id),0))+' шт.';
}
